@page "/categories"
@page "/categories/{CategorySlug}"

<PageTitle>@(CategorySlug is not null ? GetCategoryName() : "Browse Recipes") - RecipeShare</PageTitle>

@if (CategorySlug is null)
{
    <h1>Browse Recipes</h1>
    <p>Select a category to explore recipes.</p>
    <ul class="list-group">
        <li class="list-group-item"><a href="categories/appetizers">🥗 Appetizers</a></li>
        <li class="list-group-item"><a href="categories/main-courses">🍝 Main Courses</a></li>
        <li class="list-group-item"><a href="categories/desserts">🍰 Desserts</a></li>
        <li class="list-group-item"><a href="categories/beverages">🥤 Beverages</a></li>
        <li class="list-group-item"><a href="categories/baking">🍞 Baking</a></li>
        <li class="list-group-item"><a href="categories/vegetarian">🥬 Vegetarian</a></li>
    </ul>
}
else
{
    <h1>@GetCategoryName()</h1>
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
            <li class="breadcrumb-item active">@GetCategoryName()</li>
        </ol>
    </nav>

    <div class="row">
        @foreach (var recipe in GetRecipesForCategory())
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? CategorySlug { get; set; }

    private string GetCategoryName() => CategorySlug switch
    {
        "appetizers" => "Appetizers",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        "beverages" => "Beverages",
        "baking" => "Baking",
        "vegetarian" => "Vegetarian",
        _ => "Unknown Category"
    };

    private List<RecipeInfo> GetRecipesForCategory() => CategorySlug switch
    {
        "appetizers" => new()
        {
            new(1, "Bruschetta", "Classic Italian tomato and basil bruschetta on crusty bread."),
            new(2, "Stuffed Mushrooms", "Savory cream cheese and herb stuffed mushrooms.")
        },
        "main-courses" => new()
        {
            new(3, "Spaghetti Carbonara", "Creamy Italian pasta with pancetta and parmesan."),
            new(4, "Grilled Salmon", "Herb-crusted salmon fillet with lemon butter sauce.")
        },
        "desserts" => new()
        {
            new(5, "Chocolate Lava Cake", "Rich molten chocolate cake with a gooey center."),
            new(6, "Tiramisu", "Classic Italian coffee-flavored layered dessert.")
        },
        "beverages" => new()
        {
            new(7, "Mango Smoothie", "Refreshing tropical mango and yogurt smoothie."),
            new(8, "Iced Matcha Latte", "Creamy iced green tea latte.")
        },
        "baking" => new()
        {
            new(9, "Sourdough Bread", "Artisan sourdough with a crispy crust and tangy flavor."),
            new(10, "Cinnamon Rolls", "Soft, fluffy rolls with cinnamon sugar and cream cheese glaze.")
        },
        "vegetarian" => new()
        {
            new(11, "Veggie Stir Fry", "Colorful mixed vegetables in a savory soy-ginger sauce."),
            new(12, "Mushroom Risotto", "Creamy arborio rice with wild mushrooms and parmesan.")
        },
        _ => new()
    };

    private record RecipeInfo(int Id, string Title, string Description);
}

@page "/recipe/{Id:int}"

<PageTitle>@(_recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (_recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
            <li class="breadcrumb-item"><a href="categories/@_recipe.CategorySlug">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="text-muted">Category: @_recipe.Category</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in _recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <hr />
    <h4>Rate this Recipe</h4>
    <StarRating RecipeId="Id" @rendermode="InteractiveServer" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeData.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@_model.Title</strong>" with the community.</p>
        <button class="btn btn-primary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                <option value="Appetizers">Appetizers</option>
                <option value="Main Courses">Main Courses</option>
                <option value="Desserts">Desserts</option>
                <option value="Beverages">Beverages</option>
                <option value="Baking">Baking</option>
                <option value="Vegetarian">Vegetarian</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.Steps"
                placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <ValidationMessage For="() => _model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmissionModel _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        _submitted = true;
    }

    private void ResetForm()
    {
        _model = new();
        _submitted = false;
    }
}

@rendermode InteractiveServer

<div class="star-rating" aria-label="Rate this recipe from 1 to 5 stars">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _currentRating ? "filled" : "")"
              role="button"
              tabindex="0"
              aria-label="@star star@(star > 1 ? "s" : "")"
              @onclick="() => SetRating(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              style="@GetStarStyle(star)">
            ★
        </span>
    }
    @if (_currentRating > 0)
    {
