using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeSubmissionModel
{
    [Required(ErrorMessage = "Please enter a recipe title.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Please list at least one ingredient.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Please provide at least one step.")]
    public string Steps { get; set; } = "";
}

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string CategorySlug { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
}

public static class RecipeData
{
    private static readonly List<Recipe> Recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = new() { "1 French baguette", "4 ripe tomatoes, diced", "3 cloves garlic, minced", "Fresh basil leaves", "2 tbsp olive oil", "Salt and pepper to taste" },
            Steps = new() { "Slice baguette into 1/2 inch rounds and toast until golden.", "Mix diced tomatoes, garlic, basil, and olive oil in a bowl.", "Season with salt and pepper.", "Spoon tomato mixture onto toasted bread slices.", "Serve immediately." }
        },
        new Recipe
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = new() { "24 button mushrooms", "8 oz cream cheese, softened", "1/4 cup parmesan cheese", "2 cloves garlic, minced", "2 tbsp fresh parsley", "Salt and pepper" },
            Steps = new() { "Preheat oven to 375°F.", "Remove stems from mushrooms and hollow caps slightly.", "Mix cream cheese, parmesan, garlic, and parsley.", "Fill each mushroom cap with the cheese mixture.", "Bake for 20 minutes until golden and bubbly." }
        },
        new Recipe
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = new() { "400g spaghetti", "200g pancetta or guanciale", "4 egg yolks", "1 cup pecorino romano, grated", "Black pepper", "Salt for pasta water" },
            Steps = new() { "Cook spaghetti in salted boiling water until al dente.", "Crisp pancetta in a large pan over medium heat.", "Whisk egg yolks with grated pecorino and black pepper.", "Drain pasta, reserving 1 cup pasta water.", "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.", "Add pasta water as needed for a creamy sauce. Serve immediately." }
        },
        new Recipe
        {
            Id = 4, Title = "Grilled Salmon", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = new() { "4 salmon fillets", "2 tbsp olive oil", "2 lemons", "3 cloves garlic, minced", "Fresh dill", "Salt and pepper", "2 tbsp butter" },
            Steps = new() { "Season salmon with olive oil, garlic, salt, and pepper.", "Preheat grill to medium-high heat.", "Grill salmon skin-side down for 4-5 minutes.", "Flip and cook another 3-4 minutes until flaky.", "Melt butter with lemon juice and pour over salmon.", "Garnish with fresh dill and lemon slices." }
        },
        new Recipe
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = new() { "4 oz dark chocolate", "1/2 cup butter", "2 eggs", "2 egg yolks", "1/4 cup sugar", "2 tbsp flour", "Butter and cocoa for ramekins" },
            Steps = new() { "Preheat oven to 425°F. Butter and dust 4 ramekins with cocoa.", "Melt chocolate and butter together, stirring until smooth.", "Whisk eggs, yolks, and sugar until thick and pale.", "Fold chocolate mixture into eggs, then fold in flour.", "Divide batter among ramekins.", "Bake 12-14 minutes until edges are set but center is soft.", "Invert onto plates and serve immediately." }
        },
        new Recipe
        {
            Id = 6, Title = "Tiramisu", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = new() { "6 egg yolks", "3/4 cup sugar", "500g mascarpone cheese", "2 cups heavy cream", "2 cups strong espresso, cooled", "3 tbsp coffee liqueur", "24 ladyfinger cookies", "Cocoa powder" },
            Steps = new() { "Whisk egg yolks and sugar until thick and pale.", "Add mascarpone and mix until smooth.", "Whip heavy cream to stiff peaks, fold into mascarpone mixture.", "Mix espresso with coffee liqueur.", "Briefly dip ladyfingers in espresso and layer in a dish.", "Spread half the mascarpone cream over the ladyfingers.", "Repeat layers, ending with cream.", "Refrigerate at least 4 hours. Dust with cocoa before serving." }
        },
        new Recipe
        {
            Id = 7, Title = "Mango Smoothie", Category = "Beverages", CategorySlug = "beverages",
            Ingredients = new() { "2 ripe mangoes, peeled and diced", "1 cup Greek yogurt", "1/2 cup milk", "1 tbsp honey", "1/2 cup ice cubes", "Pinch of cardamom (optional)" },
            Steps = new() { "Add mango, yogurt, milk, and honey to a blender.", "Add ice cubes.", "Blend until smooth and creamy.", "Taste and adjust sweetness with more honey if needed.", "Pour into glasses and serve immediately." }
        },
        new Recipe
        {
            Id = 8, Title = "Iced Matcha Latte", Category = "Beverages", CategorySlug = "beverages",
            Ingredients = new() { "2 tsp matcha powder", "2 tbsp hot water", "1 cup milk of choice", "1 tbsp honey or sweetener", "Ice cubes" },
            Steps = new() { "Sift matcha powder into a bowl to remove clumps.", "Add hot water and whisk vigorously until smooth and frothy.", "Fill a glass with ice cubes.", "Pour milk over the ice.", "Drizzle matcha over the milk.", "Add sweetener and stir to combine." }
        },
        new Recipe
        {
            Id = 9, Title = "Sourdough Bread", Category = "Baking", CategorySlug = "baking",
            Ingredients = new() { "500g bread flour", "350g water", "100g active sourdough starter", "10g salt" },
            Steps = new() { "Mix flour, water, and starter. Rest 30 minutes (autolyse).", "Add salt and fold until incorporated.", "Stretch and fold every 30 minutes for 2 hours.", "Bulk ferment at room temperature for 4-6 hours until doubled.", "Shape into a round loaf and place in a floured banneton.", "Cold proof in refrigerator for 12-16 hours.", "Preheat oven to 500°F with a Dutch oven inside.", "Score the dough, bake covered 20 minutes, then uncovered 25 minutes." }
        },
        new Recipe
        {
            Id = 10, Title = "Cinnamon Rolls", Category = "Baking", CategorySlug = "baking",
            Ingredients = new() { "3 cups flour", "1/4 cup sugar", "1 packet yeast", "3/4 cup warm milk", "1/3 cup butter, melted", "1 egg", "For filling: 1/2 cup brown sugar, 2 tbsp cinnamon, 1/3 cup butter", "For glaze: 4 oz cream cheese, 1 cup powdered sugar, 2 tbsp milk" },
            Steps = new() { "Mix warm milk, sugar, and yeast. Let activate 5 minutes.", "Add butter, egg, and flour. Knead until smooth.", "Let rise 1 hour until doubled.", "Roll dough into a rectangle, spread softened butter, sprinkle cinnamon sugar.", "Roll tightly into a log, cut into 12 pieces.", "Place in a greased baking pan, let rise 30 minutes.", "Bake at 350°F for 22-25 minutes.", "Mix glaze ingredients and spread over warm rolls." }
        },
        new Recipe
        {
            Id = 11, Title = "Veggie Stir Fry", Category = "Vegetarian", CategorySlug = "vegetarian",
            Ingredients = new() { "2 cups broccoli florets", "1 red bell pepper, sliced", "1 cup snap peas", "2 carrots, julienned", "3 cloves garlic, minced", "1 tbsp fresh ginger", "3 tbsp soy sauce", "1 tbsp sesame oil", "Cooked rice for serving" },
            Steps = new() { "Heat sesame oil in a wok or large pan over high heat.", "Add garlic and ginger, stir-fry 30 seconds.", "Add carrots and broccoli, cook 3 minutes.", "Add bell pepper and snap peas, cook 2 minutes.", "Pour in soy sauce and toss everything together.", "Cook 1 more minute until vegetables are tender-crisp.", "Serve over steamed rice." }
        },
        new Recipe
        {
            Id = 12, Title = "Mushroom Risotto", Category = "Vegetarian", CategorySlug = "vegetarian",
            Ingredients = new() { "1.5 cups arborio rice", "8 oz mixed wild mushrooms", "1 small onion, diced", "4 cups warm vegetable broth", "1/2 cup white wine", "1/2 cup parmesan, grated", "2 tbsp butter", "2 tbsp olive oil", "Fresh thyme" },
            Steps = new() { "Sauté mushrooms in olive oil until golden, set aside.", "In the same pan, cook onion in butter until softened.", "Add arborio rice, stir to coat, cook 1 minute.", "Pour in white wine, stir until absorbed.", "Add broth one ladle at a time, stirring frequently.", "Continue adding broth for 18-20 minutes until rice is creamy and al dente.", "Stir in mushrooms, parmesan, and fresh thyme.", "Season with salt and pepper, serve immediately." }
        }
    };

    public static Recipe? GetRecipe(int id) => Recipes.FirstOrDefault(r => r.Id == id);
}

